# Shop web
The server accepts a 1-based destination rank among active stops. Removed stops leave stored-position gaps.
A started stop requires a reason unless it is done. The server's domain predicate is canonical.
A scheduling slot belongs in [notification.sentAt, next upcoming appointment.at); held and cancelled appointments are excluded.
A dropped proposal belongs to its selected store. Switching stores must not submit the previous store's file.
Run `bun test`. Time is supplied explicitly to scheduling logic.
export type Stop={id:string;position:number;removed?:boolean;startedOn?:string;status:'NEW'|'IN_PROGRESS'|'POSTPONED'|'DONE'};
export const requiresReason=(stop:Stop)=>Boolean(stop.startedOn)&&stop.status!=='DONE';
import type {Stop} from './domain';
export function moveUp(stops:Stop[],activeIndex:number){return {id:stops[activeIndex].id,position:stops[activeIndex-1].position};}
export const screenRequiresReason=(stop:Stop)=>stop.status==='IN_PROGRESS';
export function fitsWindow(at:number,notice:{sentAt:number},appointments:{at:number;status:string}[],now:number){const next=appointments.filter(a=>a.status!=='CANCELLED').sort((a,b)=>a.at-b.at)[0];return Boolean(next && at<next.at);}
import React,{useState} from 'react';
type Proposal={title:string;fileId:string};
export function PlanningScreen({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){return <ProposalForm storeId={storeId} proposal={proposal} onSubmit={onSubmit}/>;}
function ProposalForm({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){const [form,setForm]=useState<Proposal>({title:'',fileId:''});return <form onSubmit={e=>{e.preventDefault();onSubmit({storeId,...form});}}><input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><button type="button" onClick={()=>proposal&&setForm(proposal)}>Use upload</button><button type="submit">Save</button></form>;}
import {test,expect} from 'bun:test';import {fitsWindow} from './logic';test('ordinary slot',()=>expect(fitsWindow(15,{sentAt:10},[{at:20,status:'PLANNED'}],10)).toBe(true));
